mapper.select:
SELECT matched.kind, matched.id, matched.value FROM ( SELECT 'person' AS kind, p.id, p.name AS value FROM person p WHERE (p.workspace_id = #{workspaceId} OR EXISTS (SELECT 1 FROM person_share ps JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) org_workspace ON org_workspace.id = p.workspace_id WHERE ps.person_id = p.id AND ps.workspace_id = #{workspaceId})) AND p.archived_at IS NULL AND p.suspended_at IS NULL AND p.provision_ceased_at IS NULL AND p.name IS NOT NULL
UNION ALL SELECT 'company' AS kind, c.id, c.name AS value FROM company c WHERE (c.workspace_id = #{workspaceId} OR EXISTS (SELECT 1 FROM company_share cs JOIN JSON_TABLE(#{orgWorkspaceIdsJson}, '$[*]' COLUMNS(id INT PATH '$')) org_workspace ON org_workspace.id = c.workspace_id WHERE cs.company_id = c.id AND cs.workspace_id = #{workspaceId})) AND c.archived_at IS NULL AND c.name IS NOT NULL
UNION ALL SELECT 'deal' AS kind, d.id, d.name AS value FROM deal d WHERE d.workspace_id = #{workspaceId} AND d.name IS NOT NULL
) matched WHERE matched.kind > #{afterKind} OR (matched.kind = #{afterKind} AND matched.id > #{afterId}) ORDER BY matched.kind, matched.id LIMIT #{limit}
